import { isFontKey } from './editor-palette';

/**
 * The stylesheet of each editor font that index.js doesn't already load (Figtree is in the core
 * sheet). They are self-hosted (src/theme/fonts, generated by scripts/fonts/sync-fonts.mjs), so
 * choosing a font never contacts a third party; Vite emits each sheet and its woff2 files as
 * content-hashed assets under /assets and fetches them only when the key is first needed.
 */
const FONT_SHEETS: Record<string, () => Promise<unknown>> = {
  poppins: () => import('../../theme/fonts/poppins.css'),
  lora: () => import('../../theme/fonts/lora.css'),
  nunito: () => import('../../theme/fonts/nunito.css'),
  mono: () => import('../../theme/fonts/jetbrains-mono.css'),
  caveat: () => import('../../theme/fonts/caveat.css'),
};

/** The font keys whose stylesheet was requested (once each). Exported for tests. */
export const requestedFontKeys = new Set<string>();

/** Loads a font's stylesheet the first time the key is rendered or chosen; Figtree and Default need none. */
export function ensureFontLoaded(key: string): void {
  const load = FONT_SHEETS[key];
  if (!load || requestedFontKeys.has(key)) return;
  requestedFontKeys.add(key);
  load().catch(() => requestedFontKeys.delete(key));
}

/** Every font key a ProseMirror JSON doc uses. */
export function collectFontKeys(doc: unknown): Set<string> {
  const keys = new Set<string>();
  const walk = (node: unknown): void => {
    if (!node || typeof node !== 'object') return;
    const n = node as { marks?: unknown; content?: unknown };
    if (Array.isArray(n.marks)) {
      for (const mark of n.marks as Array<{ type?: string; attrs?: { fontFamily?: unknown } }>) {
        const font = mark?.attrs?.fontFamily;
        if (mark?.type === 'textStyle' && isFontKey(font)) keys.add(font);
      }
    }
    if (Array.isArray(n.content)) n.content.forEach(walk);
  };
  walk(doc);
  return keys;
}

/** Loads every font the doc uses (viewers' editors call this on load). */
export function ensureDocFontsLoaded(doc: unknown): void {
  collectFontKeys(doc).forEach(ensureFontLoaded);
}
